import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { ImageMagick, initializeImageMagick, MagickFormat } from '@imagemagick/magick-wasm';

// sample.jpg is an original 120 × 80 canvas drawing generated by generate-test-fixture.mjs.
const fixtures = new URL('../tests/fixtures/', import.meta.url);
await mkdir(fixtures, { recursive: true });
const input = await readFile(new URL('sample.jpg', fixtures));
await initializeImageMagick(await readFile(new URL(import.meta.resolve('@imagemagick/magick-wasm/magick.wasm'))));

for (const [extension, format] of [
  ['tiff', MagickFormat.Tiff],
  ['psd', MagickFormat.Psd],
  ['tga', MagickFormat.Tga],
  ['jxl', MagickFormat.Jxl],
  ['avif', MagickFormat.Avif],
  ['webp', MagickFormat.WebP],
  ['bmp', MagickFormat.Bmp],
  ['gif', MagickFormat.Gif],
]) {
  const output = ImageMagick.read(input, image => image.write(format, data => new Uint8Array(data)));
  await writeFile(new URL(`sample.${extension}`, fixtures), output);
}

await writeFile(new URL('sample.svg', fixtures), '<svg xmlns="http://www.w3.org/2000/svg" width="120" height="80" viewBox="0 0 120 80"><rect width="120" height="80" fill="#17694b"/><rect x="35" y="25" width="50" height="30" fill="white"/></svg>\n');

// magick-wasm has a HEVC decoder but no HEVC encoder. The checked-in HEIC fixture
// remains usable everywhere; regenerating it requires the macOS system encoder.
if (process.platform === 'darwin') {
  execFileSync('/usr/bin/sips', [
    '-s', 'format', 'heic',
    fileURLToPath(new URL('sample.jpg', fixtures)),
    '--out', fileURLToPath(new URL('sample.heic', fixtures)),
  ], { stdio: 'inherit' });
} else {
  await readFile(new URL('sample.heic', fixtures));
}

// Verify fixture dimensions and decoder support before writing browser expectations.
for (const extension of ['tiff', 'heic', 'psd', 'tga', 'jxl', 'avif', 'webp', 'bmp', 'gif']) {
  const bytes = await readFile(new URL(`sample.${extension}`, fixtures));
  const verify = image => {
    if (image.width !== 120 || image.height !== 80) throw new Error(`Invalid dimensions: ${extension}`);
  };
  if (extension === 'tga') ImageMagick.read(bytes, MagickFormat.Tga, verify);
  else ImageMagick.read(bytes, verify);
}
